cat > server.py << 'EOF'
import grpc
import kvstore_pb2
import kvstore_pb2_grpc
from concurrent import futures
import threading

class KVStoreService(kvstore_pb2_grpc.KVStoreServicer):
    def __init__(self):
        self.store = {}
        self.lock = threading.Lock()

    def GetVal(self, request, context):
        with self.lock:
            val = self.store.get(request.key, 0)
            return kvstore_pb2.GetValResponse(val=val)

    def SetVal(self, request, context):
        with self.lock:
            self.store[request.key] = request.val
            return kvstore_pb2.SetValResponse(val=request.val)

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    kvstore_pb2_grpc.add_KVStoreServicer_to_server(KVStoreService(), server)
    server.add_insecure_port('0.0.0.0:5328')
    server.start()
    print('Server started on port 5328')
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
EOF
